insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('124511df-5062-4ca7-9cc6-c38ef5f9435b', 'ef9d927c-9bc5-48cc-bab7-7480f35d1138', $$Big Bazar bv en de concurrentie met Action: omzetgroei$$,
   $$bedrijfseconomie-havo-2025-ii-big-bazar-bv-context1.png$$,
   $$Big Bazar bv was een winkel in goedkope huishoudelijke artikelen, die in hevige concurrentiestrijd was gewikkeld met de koopjesketen Action. De omzet van Big Bazar steeg van € 77,4 miljoen in 2021 naar € 93 miljoen in 2022. De omzet van Action steeg in diezelfde periode met ruim 30%.$$, 'inline'),
  ('0e9523e6-e45b-42cd-a220-56fb622dca1f', 'ef9d927c-9bc5-48cc-bab7-7480f35d1138', $$oplopende verliezen en schulden$$,
   $$bedrijfseconomie-havo-2025-ii-big-bazar-bv-context2.png$$,
   $$Bij Big Bazar liepen in 2021 en 2022 zowel de verliezen als de schulden op. Het bedrijf verloor marktaandeel en heeft de concurrentiestrijd met Action uiteindelijk verloren.$$, 'inline'),
  ('306be10f-440f-4aa3-9b34-2b0735fff8f5', 'ef9d927c-9bc5-48cc-bab7-7480f35d1138', $$faillissementsaanvragen en de verhuurders van winkelpanden$$,
   $$bedrijfseconomie-havo-2025-ii-big-bazar-bv-context3.png$$,
   $$In de zomer van 2023 waren tientallen faillissementsaanvragen in behandeling van Big Bazar’s schuldeisers die hun geld opeisten.
Niet alle schuldeisers van Big Bazar wilden dat Big Bazar failliet verklaard zou worden. Verhuurders van winkelpanden, waarbij Big Bazar enkele maanden huurachterstand had, waren voorstander van het faillissement.$$, 'inline'),
  ('45190773-0dfb-45d9-bb51-2f9f8fcc47cd', 'ef9d927c-9bc5-48cc-bab7-7480f35d1138', $$faillissement van Big Bazar en de schuldeisers$$,
   $$bedrijfseconomie-havo-2025-ii-big-bazar-bv-context4.png$$,
   $$In het najaar van 2023 werd Big Bazar door de rechtbank failliet verklaard. De schuldeisers van Big Bazar bestonden onder andere uit banken en de verhuurders van de winkelpanden.$$, 'inline'),
  ('c7f4d40a-4c1d-4e79-b9cc-07713d6219ef', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$inleiding: informatiebronnen 1 tot en met 3; Rianah is vrijwilliger bij de voedselbank$$,
   $$bedrijfseconomie-havo-2025-ii-stichting-voedselbank-voorwaerts-context1.png$$,
   $$Bij deze opgave horen de informatiebronnen 1 tot en met 3.
Rianah volgt de hbo-opleiding Schuldhulpverlening. Naast haar opleiding verricht zij financieel-administratieve werkzaamheden als vrijwilliger voor de Stichting Voedselbank Voorwaerts. Deze stichting verstrekt wekelijks aan meer dan 800 huishoudens gratis voedselpakketten.$$, 'inline'),
  ('97091766-f643-46b9-880a-9d74720a83eb', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$statuten van de stichting en de vereniging (informatiebron 1)$$,
   $$bedrijfseconomie-havo-2025-ii-stichting-voedselbank-voorwaerts-context2.png$$,
   $$In informatiebron 1 zijn delen van de statuten van Stichting Voedselbank Voorwaerts en delen van de statuten van de landelijke Vereniging van Voedselbanken Nederland opgenomen.$$, 'inline'),
  ('df910eb9-6b3b-483f-9a06-16d64bb2276a', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$hoogste besluitvormingsorgaan van stichting en vereniging$$,
   $$bedrijfseconomie-havo-2025-ii-stichting-voedselbank-voorwaerts-context3.png$$,
   $$Het hoogste besluitvormingsorgaan van een stichting is anders dan dat van een vereniging.$$, 'inline'),
  ('a03cd398-9090-4af4-b14e-2eb0f8fab277', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$zorgen over de verslechterde economie en de exploitatiebegroting 2024$$,
   $$bedrijfseconomie-havo-2025-ii-stichting-voedselbank-voorwaerts-context4.png$$,
   $$Het bestuur van Stichting Voedselbank Voorwaerts maakt zich in januari 2024 zorgen over de verslechterde economie in Nederland en de gevolgen daarvan voor de reeds opgestelde exploitatiebegroting van de voedselbank voor het jaar 2024 (zie informatiebron 2). Verwacht wordt dat:
− supermarkten aan hun klanten vaker korting geven op vers voedsel waarvan de houdbaarheidsdatum in zicht komt.
− er tegenvallers zijn bij de geldelijke opbrengsten en kosten van de voedselbank.
− de strengere milieueisen voor stadsverkeer de voedselbank zullen dwingen om een nieuwe milieuvriendelijke transportauto aan te schaffen.
Bij het opstellen van de exploitatiebegroting van 2024 is met bovenstaande factoren geen rekening gehouden.$$, 'inline'),
  ('181ec345-63f8-435f-8ad6-d29484e6c2f2', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$liquiditeits- en solvabiliteitspositie op 1 januari 2024$$,
   $$bedrijfseconomie-havo-2025-ii-stichting-voedselbank-voorwaerts-context5.png$$,
   $$Volgens Rianah zijn zowel de liquiditeitspositie als de solvabiliteitspositie van Voedselbank Voorwaerts op 1 januari 2024 voldoende. Rianah concludeert daaruit dat de voedselbank financieel gezond is.$$, 'inline'),
  ('80ec1152-ec79-450b-96b6-be20fa05684f', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$aanpassen van de exploitatiebegroting en vervanging van de transportauto$$,
   $$bedrijfseconomie-havo-2025-ii-stichting-voedselbank-voorwaerts-context6.png$$,
   $$Het bestuur is het niet helemaal eens met Rianah over de financiële gezondheid van de voedselbank.
Het bestuur vraagt Rianah de reeds opgestelde exploitatiebegroting voor 2024 aan te passen waarbij ze rekening moet houden met:
− een daling van € 30.000 van de opbrengsten.
− een stijging van de afschrijvingskosten als gevolg van de aanschaf van de nieuwe transportauto.
− een stijging van € 15.000 van de totale bedrijfskosten exclusief de afschrijvingskosten van de nieuwe transportauto.
Rianah neemt in haar berekeningen mee dat op 1 april 2024 de nieuwe transportauto in gebruik wordt genomen en de huidige transportauto op dezelfde datum tegen de balanswaarde wordt verkocht (zie informatiebron 3).$$, 'inline'),
  ('466fd10e-5cb6-464f-9f6f-bc79975fc715', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$minimaal eigen vermogen van € 150.000 volgens het reglement$$,
   $$bedrijfseconomie-havo-2025-ii-stichting-voedselbank-voorwaerts-context7.png$$,
   $$Rianah heeft de exploitatiebegroting aangepast en het nieuwe, verwachte resultaat over 2024 berekend. Het eigen vermogen van de Voedselbank moet, volgens het reglement van de Vereniging van Voedselbanken Nederland, minimaal € 150.000 zijn.$$, 'inline'),
  ('06a8a3f0-68bf-48b8-869f-14c0bf6ba442', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$Informatiebron 1: statuten Stichting Voedselbank Voorwaerts en Vereniging van Voedselbanken Nederland$$,
   $$bedrijfseconomie-havo-2025-ii-stichting-voedselbank-voorwaerts-informatiebron1.png$$,
   $$Informatiebron 1
Stichting Voedselbank Voorwaerts
De Stichting Voedselbank Voorwaerts in de gemeente Twello is net als de andere 171 plaatselijke voedselbanken in Nederland een zelfstandige organisatie. Alle plaatselijke voedselbanken zijn lid van de landelijke Vereniging van Voedselbanken Nederland, die de reglementen opstelt waaraan leden zich dienen te houden.
In de statuten van de Stichting Voedselbank Voorwaerts is onder andere opgenomen:
Doel De stichting heeft als doel:
− het bieden van directe voedselhulp aan de armste mensen,
− het tegengaan van verspilling van goed voedsel,
− de voedselbankactiviteiten uit te voeren zonder winstoogmerk.
De stichting tracht haar doel te bereiken door: a het uitvoeren van voedselbankactiviteiten in haar werkgebied, bijvoorbeeld door het inzamelen van voedsel¹⁾ bij supermarkten. b zich aan te sluiten bij de Vereniging van Voedselbanken Nederland en zich te houden aan de statuten van Voedselbanken Nederland.
noot 1: Een deel van het ingezamelde voedsel is vers voedsel dat tegen de houdbaarheidsdatum aanzit. Meestal wordt het voedsel gratis verstrekt, maar bij tekorten moet de voedselbank het voedsel zelf inkopen bij supermarkten.
De Vereniging van Voedselbanken Nederland.
In de statuten van de Vereniging van Voedselbanken Nederland is onder andere opgenomen:
Doel De vereniging heeft ten doel: voedselbanken in Nederland te ondersteunen bij hun taak.
De vereniging tracht dit doel onder meer te bereiken door: a het geven van voorlichting aan de aangesloten voedselbanken, b het ondersteunen van leden op diverse terreinen, c het werven van fondsen en voedsel als aanvulling op het werk van leden.$$, 'inline'),
  ('209bbb0f-70e8-457d-b388-b0c5060b732f', 'f5540f92-b4f9-4770-bdc3-6457c1f234b0', $$Informatiebron 2: balans 1 januari 2024 en exploitatiebegroting 2024$$,
